async def act(page):
    import re

    # Navigate to the Manage Products grid using a relative path
    await page.goto('/index.php/admin/catalog_product/')
    await page.wait_for_load_state('networkidle')

    # Locate the first table on the page (expected product grid)
    table = page.get_by_role('table').first
    await table.wait_for(timeout=10000)

    rows = table.get_by_role('row')
    rows_count = await rows.count()

    header_row_idx = None
    qty_idx = None
    brand_idx = None

    # Scan the first several rows to locate header and determine column indices
    scan_limit = min(10, rows_count)
    for i in range(scan_limit):
        row = rows.nth(i)
        try:
            cells_texts = await row.get_by_role('cell').all_inner_texts()
        except Exception:
            cells_texts = []
        lowered = [(t or '').strip().lower() for t in cells_texts]
        if any('qty' in s or 'quantity' in s or 'sku' in s or 'name' in s or 'price' in s for s in lowered):
            header_row_idx = i
            for idx, s in enumerate(lowered):
                if qty_idx is None and ('qty' in s or 'quantity' in s):
                    qty_idx = idx
                if brand_idx is None and ('brand' in s or 'manufacturer' in s):
                    brand_idx = idx
            break

    start_row = (header_row_idx + 1) if header_row_idx is not None else 0

    matching_brands = []

    for ri in range(start_row, rows_count):
        row = rows.nth(ri)
        try:
            cells = await row.get_by_role('cell').all_inner_texts()
        except Exception:
            continue
        if not cells:
            continue

        # Determine whether this row's quantity equals 3 (look for word-boundary '3')
        row_qty_matches = False
        if qty_idx is not None and qty_idx < len(cells):
            if re.search(r'\b3\b', (cells[qty_idx] or '').strip()):
                row_qty_matches = True
        else:
            for c in cells:
                if re.search(r'\b3\b', (c or '').strip()):
                    row_qty_matches = True
                    break

        if not row_qty_matches:
            continue

        # Extract brand value
        brand_val = None
        if brand_idx is not None and brand_idx < len(cells):
            brand_val = (cells[brand_idx] or '').strip()
        else:
            # Heuristic: first non-empty, non-price, non-pure-number, non-qty cell
            for c in cells:
                txt = (c or '').strip()
                if not txt:
                    continue
                if re.search(r'\b3\b', txt):
                    continue
                # skip price/number-like cells
                if re.match(r'^[\$\d\.,\s-]+$', txt):
                    continue
                brand_val = txt
                break
            if brand_val is None and len(cells) > 0:
                brand_val = (cells[0] or '').strip()

        if brand_val:
            matching_brands.append(brand_val)

    # Deduplicate while preserving order and print one per line
    seen = set()
    unique_brands = []
    for b in matching_brands:
        if b and b not in seen:
            seen.add(b)
            unique_brands.append(b)

    if unique_brands:
        print('\n'.join(unique_brands))
    else:
        # print an empty line to indicate no matches
        print('')

